<?php
require __DIR__.'/bootstrap.php';
use RK\AIVisualizer\Definitions\Registry; use RK\AIVisualizer\Core\Validation; use RK\AIVisualizer\Core\Prompt; use RK\AIVisualizer\Core\Quota; use RK\AIVisualizer\Core\Leads; use RK\AIVisualizer\Core\Engine; use RK\AIVisualizer\Providers\Factory; use RK\AIVisualizer\Frontend\Renderer;
$tests=0;$failed=0;$run=function($name,$fn)use(&$tests,&$failed){$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failed++;echo "FAIL $name: ".$e->getMessage()." (".$e->getFile().":".$e->getLine().")\n".$e->getTraceAsString()."\n";}};
$definition=Registry::instance()->get('flooring');
$run('flooring definition is registered and options match reference',function()use($definition){t_assert($definition!==null,'definition missing');$fields=$definition->fields();$by=array();foreach($fields as $f)$by[$f['id']]=$f;t_eq(array_keys($by),array('roomType','projectType','preferredStyle','customStyleDescription','woodSpecies','floorDirection','finishPreference','sheen','serviceCity','squareFootage'));t_eq(array_keys($by['roomType']['options']),array('kitchen','living_room','hallway','bedroom','office','retail_gym'));t_eq($by['finishPreference']['options']['rubio_monocoat'],'Rubio Monocoat');});
$run('upload validation accepts JPEG/PNG/WebP sized image and checks dimensions',function()use($definition){$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$r=new WP_REST_Request();$r->files=array('image'=>array('tmp_name'=>$f,'error'=>0));$u=Validation::upload($r,$definition);t_assert(is_array($u)&&'image/png'===$u['mime'],'valid PNG rejected');file_put_contents($f,test_png(100,100));t_error(Validation::upload($r,$definition),'rk_viz_too_small','small image');file_put_contents($f,'not image');t_error(Validation::upload($r,$definition),'rk_viz_bad_type','invalid type');unlink($f);});
$run('generic field validation rejects invalid option and requires custom description',function()use($definition){$bad=valid_options(array('sheen'=>'shiny'));t_error(Validation::fields($bad,$definition),'rk_viz_bad_options','bad option');$bad=valid_options(array('preferredStyle'=>'custom'));t_error(Validation::fields($bad,$definition),'rk_viz_bad_options','missing custom style');$ok=Validation::fields(valid_options(array('preferredStyle'=>'custom','customStyleDescription'=>'deep walnut')),$definition);t_assert(is_array($ok),'custom input rejected');t_eq($ok['customStyleDescription'],'deep walnut');});
$run('prompt uses definition prompt rules and user selections',function()use($definition){$p=Prompt::build($definition,valid_options(array('woodSpecies'=>'hickory','preferredStyle'=>'gray_weathered','floorDirection'=>'herringbone','sheen'=>'satin','finishPreference'=>'rubio_monocoat')));foreach(array('photorealistic','hickory hardwood','gray, weathered tone','herringbone','satin sheen','hardwax oil','Do not change the walls.') as $needle)t_assert(false!==strpos($p,$needle),'missing prompt fragment: '.$needle);$c=Prompt::build($definition,valid_options(array('preferredStyle'=>'custom','customStyleDescription'=>'deep walnut')));t_assert(false!==strpos($c,'deep walnut'),'custom prompt missing');});
$run('quota consumes and refunds generations while preserving cooldown',function(){ $cfg=array('free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24);$s=array('used'=>0,'bonus_used'=>0,'lead'=>false,'next_at'=>0);t_eq(Quota::status($s,$cfg,100)['freeRemaining'],2);$spent=Quota::consume($s,'free',$cfg,100);t_eq($spent['used'],1);t_eq(Quota::refund($spent,'free',$s)['used'],0);$s['used']=2;t_eq(Quota::status($s,$cfg,100)['phase'],'needs_lead');$s['lead']=true;t_eq(Quota::status($s,$cfg,100)['phase'],'bonus');});
$run('lead validation and deduplicated visualizer association',function(){t_assert(isset(Leads::validate(array('name'=>'','email'=>'bad'))['errors']),'bad lead accepted');$good=Leads::validate(array('name'=>'Pat Smith','email'=>'Pat@Example.com','phone'=>'(309) 555-0100'));t_eq($good['lead']['email'],'pat@example.com');t_assert(isset(Leads::validate(array('name'=>'Pat','email'=>'p@example.com','phone'=>'call me 3095550100'))['errors']),'alphabetic phone accepted');Leads::store($good['lead'],'flooring','gen-one');t_eq(count(Leads::all()),1);t_eq(Leads::all()[0]['visualizer'],'flooring');t_assert(!isset(Leads::all()[0]['ip']),'raw IP was retained with lead');Leads::store($good['lead'],'flooring','gen-two');t_eq(count(Leads::all()),1);});
$run('mock provider returns normalized successful output and renderer renders all fields',function()use($definition){$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$provider=Factory::create('mock');$r=$provider->generate(array('image_path'=>$f));t_eq($r['status'],'completed');t_assert(false!==strpos($r['image_url'],'rk-ai-visualizer/'),'result not safely stored');$html=Renderer::shortcode(array('cities'=>"Peoria\nPeoria Heights"));foreach(array('name="roomType"','value="retail_gym"','value="semi_gloss"','value="peoria_heights"','data-viz-lead') as $needle)t_assert(false!==strpos($html,$needle),'renderer missing '.$needle);unlink($f);});
$run('engine mock generation returns result, counts quota, and denies after free uses',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'mock','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10));$_COOKIE['rk_ai_viz']=str_repeat('a',32);$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$e=new Engine();$r=$e->generate('flooring',request_generate($f));t_assert($r instanceof WP_REST_Response,'expected response');t_eq($r->get_data()['status'],'success');t_eq($r->get_headers()['Cache-Control'],'no-store, private');$e->generate('flooring',request_generate($f));$denied=$e->generate('flooring',request_generate($f));t_eq($denied->get_status(),429);t_eq($denied->get_data()['phase'],'needs_lead');unlink($f);});
$run('Hugging Face async polling, owner authorization, and failure refunds',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'huggingface','hf_token'=>'test-token','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>20,'timeout'=>120));$script=array(array('code'=>200,'body'=>json_encode(array('request_id'=>'r1','status_url'=>'https://queue.fal.run/fal-ai/x/status','response_url'=>'https://queue.fal.run/fal-ai/x'))),array('code'=>200,'body'=>json_encode(array('status'=>'IN_PROGRESS'))),array('code'=>200,'body'=>json_encode(array('status'=>'COMPLETED'))),array('code'=>200,'body'=>json_encode(array('images'=>array(array('url'=>'https://cdn.example.com/result.png'))))));$calls=array();$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function($pre,$method,$url,$args)use(&$script,&$calls){$calls[]=array($method,$url,$args);return array_shift($script);};$_COOKIE['rk_ai_viz']=str_repeat('b',32);$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$e=new Engine();$r=$e->generate('flooring',request_generate($f));$d=$r->get_data();t_eq($d['status'],'pending');$poll=new WP_REST_Request();$poll->params['job']=$d['job'];$_COOKIE['rk_ai_viz']=str_repeat('c',32);t_error($e->status($poll),'rk_viz_no_job','foreign owner');$_COOKIE['rk_ai_viz']=str_repeat('b',32);t_eq($e->status($poll)->get_data()['status'],'pending');$done=$e->status($poll);t_eq($done->get_data()['status'],'success');t_eq($done->get_data()['imageUrl'],'https://cdn.example.com/result.png');t_assert(false===strpos($calls[0][1],'test-token'),'token leaked into URL');t_eq($calls[0][2]['limit_response_size'],20971520,'provider response cap missing');t_eq($calls[0][2]['redirection'],0,'provider redirects enabled');t_eq($calls[0][2]['reject_unsafe_urls'],true,'WordPress safe URL flag missing');unlink($f);unset($GLOBALS['wp_filters']['rk_ai_visualizer_http']);});
$run('remote custom backend status URLs must stay on configured HTTPS host',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'custom','custom_url'=>'https://api.example.com/visualize','custom_key'=>'secret','custom_header'=>'X-Key','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10));$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function(){return array('code'=>200,'body'=>json_encode(array('statusUrl'=>'https://evil.example.net/job')));};$_COOKIE['rk_ai_viz']=str_repeat('d',32);$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$e=new Engine();t_error($e->generate('flooring',request_generate($f)),'rk_viz_provider','unsafe status URL');$state=get_transient('rk_ai_viz_flooring_'.substr(hash('sha256',str_repeat('d',32)),0,32));t_eq($state['used'],0,'provider failure should refund quota');unlink($f);unset($GLOBALS['wp_filters']['rk_ai_visualizer_http']);});
$run('definition lookup, unknown definitions, and response security',function(){ $e=new Engine(); t_assert($e->definition('missing')===null,'unknown definition exists');$r=$e->quota('missing');t_error($r,'rk_viz_definition','unknown definition response');});
$run('upload size cap rejects oversized images before decoding',function()use($definition){$f=tempnam(sys_get_temp_dir(),'rkbig');$h=fopen($f,'wb');ftruncate($h,10485761);fclose($h);$r=new WP_REST_Request();$r->files=array('image'=>array('tmp_name'=>$f,'error'=>0));t_error(Validation::upload($r,$definition),'rk_viz_too_large','oversized image');unlink($f);});
$run('asynchronous provider failure refunds the reserved generation',function(){$cfg=array('enabled'=>true,'provider'=>'huggingface','hf_token'=>'fake-token','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10,'timeout'=>120);update_option('rk_ai_visualizer_settings',$cfg);$script=array(array('code'=>200,'body'=>json_encode(array('status_url'=>'https://queue.fal.run/job/status','response_url'=>'https://queue.fal.run/job'))),array('code'=>200,'body'=>json_encode(array('status'=>'FAILED'))));$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function()use(&$script){return array_shift($script);};$_COOKIE['rk_ai_viz']=str_repeat('e',32);$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$engine=new Engine();$started=$engine->generate('flooring',request_generate($f))->get_data();$key='rk_ai_viz_flooring_'.substr(hash('sha256',str_repeat('e',32)),0,32);t_eq(get_transient($key)['used'],1,'reservation counted while running');$poll=new WP_REST_Request();$poll->params['job']=$started['job'];t_error($engine->status($poll),'rk_viz_provider','failed async job');t_eq(get_transient($key)['used'],0,'failed async job was refunded');unlink($f);unset($GLOBALS['wp_filters']['rk_ai_visualizer_http']);});
$run('REST registration exposes definition-aware and legacy Flooring paths',function(){\RK\AIVisualizer\Rest\Routes::register();$found=array();foreach($GLOBALS['wp_routes'] as $r)$found[]=$r[0].$r[1];foreach(array('rk-ai/v1/visualizer/quota','rk-ai/v1/visualizer/(?P<visualizer>[a-z0-9_-]+)/generate','rk/v1/visualizer/status','rk/v1/visualizer/(?P<visualizer>[a-z0-9_-]+)/lead') as $route)t_assert(in_array($route,$found,true),'route not registered: '.$route);});
$run('Engine supports explicit nullable and injected registry construction',function(){$parameter=(new ReflectionMethod(Engine::class,'__construct'))->getParameters()[0];t_assert($parameter->allowsNull(),'constructor registry must explicitly allow null');t_assert((new Engine(null)) instanceof Engine,'null registry fallback failed');t_assert((new Engine(new Registry())) instanceof Engine,'explicit registry injection failed');});
$run('Definition rejects unsupported fields and invalid condition references',function()use($definition){$data=$definition->get();$data['fields'][0]['type']='image';try{new \RK\AIVisualizer\Definitions\Definition($data);throw new RuntimeException('unsupported image option field was accepted');}catch(InvalidArgumentException $e){}$data=$definition->get();$data['fields'][0]['visible_when']=array('field'=>'missingField','equals'=>'yes');try{new \RK\AIVisualizer\Definitions\Definition($data);throw new RuntimeException('unknown condition field was accepted');}catch(InvalidArgumentException $e){}$data=array('slug'=>'numeric-options','name'=>'Numeric options','fields'=>array(array('id'=>'level','type'=>'select','label'=>'Level','options'=>array(0=>'None',1=>'One'))));t_assert(new \RK\AIVisualizer\Definitions\Definition($data) instanceof \RK\AIVisualizer\Definitions\Definition,'valid integer option keys rejected');});
$run('Rolling quota failure restores the prior cooldown timestamp',function(){$cfg=array('free_count'=>1,'bonus_count'=>0,'cooldown_hours'=>24);$before=array('used'=>1,'bonus_used'=>0,'lead'=>true,'next_at'=>0);$spent=Quota::consume($before,'rolling',$cfg,1000);t_eq($spent['next_at'],87400);$restored=Quota::refund($spent,'rolling',$before);t_eq($restored['next_at'],0);t_eq($restored['used'],1);});
$run('Provider HTTP rejects credentialed and non-HTTPS URLs without network calls',function(){t_error(\RK\AIVisualizer\Providers\Http::request('GET','https://user:pass@api.example.com/x'),'rk_viz_remote_url','credentialed URL');t_error(\RK\AIVisualizer\Providers\Http::request('GET','http://api.example.com/x'),'rk_viz_remote_url','plain HTTP URL');t_eq(\RK\AIVisualizer\Providers\Http::json(array('code'=>200)) ,null,'missing response body');});
$run('Async status is bound to the definition slug in its REST path',function(){$cookie=str_repeat('j',32);$_COOKIE['rk_ai_viz']=$cookie;$id=str_repeat('a',24);set_transient('rk_ai_viz_job_'.$id,array('slug'=>'flooring','provider'=>'mock','job'=>array(),'owner'=>hash('sha256',$cookie),'phase'=>'free','before'=>array('used'=>0,'bonus_used'=>0,'lead'=>false,'next_at'=>0),'started'=>time()),3600);$r=new WP_REST_Request();$r->params['job']=$id;t_error((new Engine())->status($r,'kitchen'),'rk_viz_no_job','cross-definition status request');});
$run('Failed async job persistence refunds its reservation',function(){$cfg=array('enabled'=>true,'provider'=>'huggingface','hf_token'=>'fake-token','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10,'timeout'=>120);update_option('rk_ai_visualizer_settings',$cfg);$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function(){return array('code'=>200,'body'=>json_encode(array('status_url'=>'https://queue.fal.run/job/status','response_url'=>'https://queue.fal.run/job')));};$cookie=str_repeat('c',32);$_COOKIE['rk_ai_viz']=$cookie;$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$stateKey='rk_ai_viz_flooring_'.substr(hash('sha256',$cookie),0,32);$GLOBALS['fail_transient_prefixes']=array('rk_ai_viz_job_');$r=(new Engine())->generate('flooring',request_generate($f));t_error($r,'rk_viz_job_storage','job persistence failure');t_eq(get_transient($stateKey)['used'],0,'orphan reservation not refunded');unset($GLOBALS['fail_transient_prefixes'],$GLOBALS['wp_filters']['rk_ai_visualizer_http']);unlink($f);});
$run('Numeric sliders clamp and toggle conditions normalize consistently',function(){$d=new \RK\AIVisualizer\Definitions\Definition(array('slug'=>'generic-controls','name'=>'Generic controls','fields'=>array(array('id'=>'amount','type'=>'slider','label'=>'Amount','min'=>0,'max'=>10),array('id'=>'enabled','type'=>'toggle','label'=>'Enabled'),array('id'=>'note','type'=>'text','label'=>'Note','visible_when'=>array('field'=>'enabled','equals'=>true),'required_when'=>array('field'=>'enabled','equals'=>true)))));$v=Validation::fields(array('amount'=>'19','enabled'=>true,'note'=>'hello'),$d);t_eq($v['amount'],10.0);t_eq($v['enabled'],true);t_error(Validation::fields(array('amount'=>2,'enabled'=>true,'note'=>''),$d),'rk_viz_bad_options','conditional required field');$hidden=Validation::fields(array('amount'=>2,'enabled'=>false,'note'=>'ignored'),$d);t_eq($hidden['note'],'','hidden field value');t_error(Validation::fields(array('amount'=>'bad','enabled'=>'yes'),$d),'rk_viz_bad_options','invalid control input');});
$run('Local IP provider destinations are rejected before HTTP filters',function(){t_error(\RK\AIVisualizer\Providers\Http::request('GET','https://127.0.0.1/private'),'rk_viz_remote_url','loopback provider URL');$hf=Factory::create('huggingface');t_error($hf->poll(array('status_url'=>'https://router.huggingface.co/fal-ai/job/status?_subdomain=queue','response_url'=>'https://127.0.0.1/private')),'rk_viz_provider','tampered Hugging Face result URL');});
$run('Custom status URL cannot switch to another port on the configured host',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'custom','custom_url'=>'https://api.example.com/visualize','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10));$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function(){return array('code'=>200,'body'=>json_encode(array('statusUrl'=>'https://api.example.com:8443/job')));};$cookie=str_repeat('2',32);$_COOKIE['rk_ai_viz']=$cookie;$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$stateKey='rk_ai_viz_flooring_'.substr(hash('sha256',$cookie),0,32);t_error((new Engine())->generate('flooring',request_generate($f)),'rk_viz_provider','non-origin status port');t_eq(get_transient($stateKey)['used'],0,'unsafe status URL did not refund quota');unset($GLOBALS['wp_filters']['rk_ai_visualizer_http']);unlink($f);});
$run('Quota reservation fails closed when transient storage cannot persist',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'mock','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10));$cookie=str_repeat('3',32);$_COOKIE['rk_ai_viz']=$cookie;$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$stateKey='rk_ai_viz_flooring_'.substr(hash('sha256',$cookie),0,32);$GLOBALS['fail_transient_keys']=array($stateKey);t_error((new Engine())->generate('flooring',request_generate($f)),'rk_viz_quota_storage','failed reservation write');t_assert(false===get_transient($stateKey),'quota state unexpectedly persisted');unset($GLOBALS['fail_transient_keys']);unlink($f);});
$run('Lead option write failure is reported instead of silently accepted',function(){$good=Leads::validate(array('name'=>'Avery Smith','email'=>'avery-storage@example.com'));$GLOBALS['fail_option_keys']=array(Leads::OPTION);t_error(Leads::store($good['lead'],'flooring','storage-check'),'rk_viz_lead_storage','failed lead write');unset($GLOBALS['fail_option_keys']);});
$run('Per-IP limiting rejects requests before image file parsing',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'mock','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>1));$_COOKIE['rk_ai_viz']=str_repeat('4',32);$_SERVER['REMOTE_ADDR']='192.0.2.45';$r=new WP_REST_Request();$r->params['options']=json_encode(valid_options());t_error((new Engine())->generate('flooring',$r),'rk_viz_no_image','first missing-file request');$limited=(new Engine())->generate('flooring',$r);t_assert($limited instanceof WP_REST_Response,'IP limiter should return REST response');t_eq($limited->get_status(),429,'IP cap not enforced before upload parsing');});
$run('Async provider adapters reject non-2xx polling responses',function(){$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function(){return array('code'=>503,'body'=>json_encode(array('status'=>'processing')));};update_option('rk_ai_visualizer_settings',array('custom_url'=>'https://api.example.com/status','hf_token'=>'fake-token'));$custom=Factory::create('custom')->poll(array('status_url'=>'https://api.example.com/status/job'));t_assert(is_wp_error($custom),'custom poll treated HTTP 503 as pending');$hf=Factory::create('huggingface')->poll(array('status_url'=>'https://router.huggingface.co/fal-ai/job/status?_subdomain=queue','response_url'=>'https://router.huggingface.co/fal-ai/job/result?_subdomain=queue'));t_assert(is_wp_error($hf),'Hugging Face poll treated HTTP 503 as pending');unset($GLOBALS['wp_filters']['rk_ai_visualizer_http']);});
echo "\n$tests tests, $failed failures\n"; exit($failed?1:0);
